package predict

import "unicode"

// pi-tui's editor (Pi, and Kimi Code, which bundles the same library) wraps
// each logical line with wordWrapLine: a line that fits stays whole;
// otherwise it breaks after the last whitespace before a word, or between
// CJK characters, and force-breaks a word that does not fit. Whitespace at
// the end of a row stays on that row (nothing is hidden). A paste marker is
// one atomic segment. Ported from @earendil-works/pi-tui 1.5
// (components/editor.js); TestPiWrapMatchesPiTui checks it against vectors
// generated by the JavaScript original.

// piWhitespace is JavaScript's /\s/ for one element.
func piWhitespace(e Elem) bool {
	if e.Token {
		return false
	}
	for _, r := range e.S {
		return unicode.IsSpace(r) || r == 0xfeff
	}
	return false
}

// piCJK approximates pi-tui's cjkBreakRegex (Script_Extensions Han,
// Hiragana, Katakana, Hangul or Bopomofo), including the CJK punctuation
// whose script extensions list Han.
func piCJK(e Elem) bool {
	if e.Token {
		return false
	}
	for _, r := range e.S {
		if unicode.In(r, unicode.Han, unicode.Hiragana, unicode.Katakana, unicode.Hangul, unicode.Bopomofo) {
			return true
		}
		return r >= 0x3000 && r <= 0x303f || r >= 0xff01 && r <= 0xff65 || r == 0x30fb || r == 0x30fc
	}
	return false
}

// piWrap lays out elems at width columns like pi-tui's layoutText.
func piWrap(elems []Elem, width int) []VisualRow {
	width = max(1, width)
	var rows []VisualRow
	for _, line := range logicalLines(elems) {
		rows = append(rows, piWrapLine(elems, line[0], line[1], width)...)
	}
	return rows
}

func piWrapLine(elems []Elem, start, end, maxWidth int) []VisualRow {
	total := 0
	for i := start; i < end; i++ {
		total += elemWidth(elems[i])
	}
	if total <= maxWidth {
		return []VisualRow{{Start: start, End: end, Width: total}}
	}
	var rows []VisualRow
	chunkStart, current := start, 0
	opp, oppWidth := -1, 0
	push := func(to int) {
		w := 0
		for i := chunkStart; i < to; i++ {
			w += elemWidth(elems[i])
		}
		rows = append(rows, VisualRow{Start: chunkStart, End: to, Width: w})
	}
	for i := start; i < end; i++ {
		g := elems[i]
		gw := elemWidth(g)
		ws := piWhitespace(g)
		if current+gw > maxWidth {
			if opp >= 0 && current-oppWidth+gw <= maxWidth {
				push(opp)
				chunkStart = opp
				current -= oppWidth
			} else if chunkStart < i {
				push(i)
				chunkStart = i
				current = 0
			}
			opp = -1
		}
		if gw > maxWidth {
			// An atomic segment wider than a row (a paste marker in a narrow
			// terminal) is split visually; not predicted (see piFits).
			push(i)
			chunkStart, current, opp = i, gw, -1
			continue
		}
		current += gw
		if i+1 < end {
			next := elems[i+1]
			switch {
			case ws && !piWhitespace(next):
				opp, oppWidth = i+1, current
			// pi-tui's whitespace test is an unanchored /\s/, true for a paste
			// marker (it contains spaces): no CJK break before a marker.
			case !ws && !piWhitespace(next) && !next.Token && (piCJK(g) || piCJK(next)):
				opp, oppWidth = i+1, current
			}
		}
	}
	push(end)
	return rows
}

// piFits: every element is narrower than a row, so piWrap is exact.
func piFits(elems []Elem, width int) bool {
	for _, e := range elems {
		if elemWidth(e) > width {
			return false
		}
	}
	return true
}
